<div class="modal fade" id="modalAco" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title" id="tituloModalAco">Novo aço</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="acao" value="salvar"><input type="hidden" name="id" id="aco_id"><div class="row g-3"><div class="col-md-4"><label class="form-label">Código *</label><input class="form-control" name="codigo" id="aco_codigo" required></div><div class="col-md-8"><label class="form-label">Descrição *</label><input class="form-control" name="descricao" id="aco_descricao" required></div><div class="col-md-4"><label class="form-label">Grupo</label><input class="form-control" name="grupo" id="aco_grupo"></div><div class="col-md-4"><label class="form-label">Especial</label><select class="form-select" name="especial" id="aco_especial"><option value="0">Não</option><option value="1">Sim</option></select></div><div class="col-md-4"><label class="form-label">Ativo</label><select class="form-select" name="ativo" id="aco_ativo"><option value="1">Sim</option><option value="0">Não</option></select></div><div class="col-md-6"><label class="form-label">Peso líquido</label><input type="number" class="form-control" name="peso_liquido" id="aco_peso" min="0" step="0.000001" value="0"></div><div class="col-md-6"><label class="form-label">Espessura</label><input type="number" class="form-control" name="espessura" id="aco_espessura" min="0" step="0.01" value="0"></div></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form></div></div></div>